package com.example.starter.domain;

/**
 * 频道。
 *
 * @param id               频道 ID
 * @param fallbackAssetId  保底素材 ID；空档、无编排或授权失效时播出，不会被撤销
 */
public record Channel(String id, String fallbackAssetId) {
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 授权：关联频道与普通素材，有效区间为左闭右开 [validFrom, validTo)。
 * 创建后只能撤销，不能修改。
 *
 * @param id        授权 ID，服务端生成
 * @param channelId 频道 ID
 * @param assetId   素材 ID
 * @param validFrom 生效时间（含），UTC 时刻
 * @param validTo   失效时间（不含），UTC 时刻
 * @param revoked   是否已撤销；撤销后不可恢复
 */
public record Grant(String id, String channelId, String assetId,
                    Instant validFrom, Instant validTo, boolean revoked) {

    /**
     * 判断该授权是否未撤销且有效区间完整覆盖 [start, end)。
     */
    public boolean covers(Instant start, Instant end) {
        return !revoked && !validFrom.isAfter(start) && !validTo.isBefore(end);
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 播出片段：草稿与发布快照共用。
 *
 * @param segmentId 片段独立 ID（草稿内唯一）
 * @param assetId   素材 ID
 * @param start     播出开始时间（含），UTC 时刻，毫秒精度
 * @param end       播出结束时间（不含），UTC 时刻，毫秒精度
 */
public record DraftSegment(String segmentId, String assetId, Instant start, Instant end) {
}

package com.example.starter.domain;

import java.time.LocalDate;
import java.util.List;

/**
 * 某一“频道＋业务日”的编排草稿。整份替换，版本从 1 开始递增。
 *
 * @param channelId   频道 ID
 * @param businessDay 业务日（Asia/Shanghai 日历日）
 * @param version     草稿版本，每次成功替换加 1
 * @param segments    片段列表，按开始时间升序保存
 */
public record Draft(String channelId, LocalDate businessDay, long version,
                    List<DraftSegment> segments) {
}

package com.example.starter.domain;

import java.time.LocalDate;
import java.util.List;

/**
 * 某一“频道＋业务日”的已发布编排快照，只读；授权撤销不改写历史快照。
 *
 * @param channelId    频道 ID
 * @param businessDay  业务日（Asia/Shanghai 日历日）
 * @param version      发布版本，每次成功发布加 1
 * @param draftVersion 生成该快照时的草稿版本
 * @param segments     快照片段列表，按开始时间升序
 */
public record PublishedSchedule(String channelId, LocalDate businessDay, long version,
                                long draftVersion, List<DraftSegment> segments) {
}

