    /**
     * 新增素材；ID 已存在时抛 {@link DuplicateKeyException}。
     */
    void insert(Asset asset);

    Optional<Asset> findById(String id);
}

package com.example.starter.repo;

/**
 * 主键冲突：对应实体已存在，由服务层转换为 409。
 */
