  created_at BIGINT NOT NULL COMMENT '创建时间，Unix 毫秒'
) COMMENT='频道';

CREATE TABLE IF NOT EXISTS grants (
  id VARCHAR(64) PRIMARY KEY COMMENT '授权 ID',
  channel_id VARCHAR(128) NOT NULL COMMENT '频道 ID',
  asset_id VARCHAR(128) NOT NULL COMMENT '素材 ID',
  valid_from BIGINT NOT NULL COMMENT '生效时间（含），Unix 毫秒',
  valid_to BIGINT NOT NULL COMMENT '失效时间（不含），Unix 毫秒',
  revoked BOOLEAN NOT NULL DEFAULT FALSE COMMENT '是否已撤销',
  created_at BIGINT NOT NULL COMMENT '创建时间，Unix 毫秒',
  INDEX idx_grants_cover (channel_id, asset_id, revoked, valid_from, valid_to)
) COMMENT='授权';
```

H2 in MySQL mode: `INDEX idx ...` inside CREATE TABLE is MySQL-specific; H2 MODE=MySQL supports it I believe. H2 supports `INDEX(col)` in CREATE TABLE? In MySQL compatibility mode, yes, H2 supports KEY/INDEX definitions. I'll keep it but be ready to remove if H2 test fails. Actually to reduce risk, skip secondary indexes — not needed for correctness. Keep schema minimal and portable. I'll drop the INDEX clause.

