) COMMENT='已发布编排';

CREATE TABLE IF NOT EXISTS published_segments (
  channel_id, business_day, published_version, segment_id, asset_id, start_ms, end_ms, seq,
  PRIMARY KEY (channel? channel_id, business_day, segment_id)
) COMMENT='发布快照片段';

CREATE TABLE IF NOT EXISTS request_dedup (
  request_id VARCHAR(128) PRIMARY KEY COMMENT '客户端请求 ID',
